#include <iostream>
using std::cin;
using std::cout;
using std::cerr;
using std::endl;
#include <vector>
using std::vector;
using std::pair;
using std::make_pair;
using std::min;

typedef long long int ll;

#include <atcoder/modint>
using mint = atcoder::modint998244353;

ll n, m;
vector<mint> a, b;

void solve () {
	// line up their indexs
	a.insert(a.begin(), 0);
	n++;
	b.insert(b.begin(), 0);
	m++;

	// sum[i]  := sum_{k < i} a[k] * 1
	// sum2[i] := sum_{k < i} a[k] * k
	vector<mint> sum(n+1, 0), sum2(n+1, 0);
	for (ll i = 0; i < n; i++) {
		sum[ i+1] = sum[ i] + a[i] * 1;
		sum2[i+1] = sum2[i] + a[i] * i;
	}

	mint ans = 0;
	for (ll bi = 1; bi < m; bi++) {
		mint bans = 0;
		for (ll i = 0; i * bi < n; i++) {
			ll l = (i+0) * bi;
			ll r = min((i+1) * bi, n);

			// sum_{l <= k < r} a[k] * (k - i*bi)
			bans += (sum2[r] - sum2[l]);
			bans -= (sum[r] - sum[l]) * (i*bi);
		}
		ans += bans * b[bi];
	}

	cout << ans.val() << "\n";
}

int main (void) {
	std::cin.tie(nullptr);
	std::ios_base::sync_with_stdio(false);

	cin >> n >> m;

	a.resize(n);
	for (ll i = 0; i < n; i++) {
		ll x; cin >> x;
		a[i] = x;
	}
	b.resize(m);
	for (ll i = 0; i < m; i++) {
		ll x; cin >> x;
		b[i] = x;
	}

	solve();

	return 0;
}

#include <bits/stdc++.h>
#include <atcoder/all>
using namespace std;
using mint = atcoder::modint998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    // 実装上は、 B についても長さを 1 増やし、1-indexedとして扱えるようにします。
    vector<mint> A(N+1), B(M+1);
    for (int i = 1; i <= N; i++) {
        int x;
        cin >> x;
        A[i] = x;
    }
    for (int j = 1; j <= M; j++) {
        int x;
        cin >> x;
        B[j] = x;
    }

    vector<mint> C(N+1);
    for (int i = 0; i <= N; i++) C[i] = A[i] * i;

    // A と C の累積和
    vector<mint> acc_A(N+2), acc_C(N+2);
    for (int i = 0; i <= N; i++) {
        acc_A[i+1] = acc_A[i] + A[i];
        acc_C[i+1] = acc_C[i] + C[i];
    }

    auto f = [&](int l, int r) -> mint {
        r = min(r, N+1); // N+1 とのminをとると、 i > N となる A_i を陽に持たなくても良いです。

        return (acc_C[r] - acc_C[l]) - l * (acc_A[r] - acc_A[l]);
    };

    mint ans = 0;
    for (int j = 1; j <= M; j++) {
        mint x = 0;
        for (int k = 0; k < (N+1 + j - 1) / j; k++) {
            x += f(j*k, j*k + j);
        }
        ans += x * B[j];
    }
    cout << ans.val() << endl;
}
